// Shell problem — C++ equivalent of: head -n 10 file.txt | tail -n 1
#include <bits/stdc++.h>
using namespace std;
int main() {
    ifstream fin("file.txt");
    string line, tenth;
    int seen = 0;
    while (seen < 10 && getline(fin, line)) tenth = line, ++seen;
    if (seen == 10) cout << tenth << "\n";
}

